template <typename T>
void wrapper(T&& arg) {
    // T&& is a Universal Reference (can be lvalue or rvalue)
    target(std::forward<T>(arg));
}

// ------ How std::forward works ------
// When arg is L-value (T becomes T&):
// std::forward<T&>(arg) -> static_cast<T&>(arg) -> L-value
// When arg is R-value (T becomes actual type U):
// std::forward<U>(arg) -> static_cast<U&&>(arg) -> R-value

